    48  void LJpegDecompressor::decodeScan()
    49  {
    50    if (predictorMode != 1)
    51      ThrowRDE("Unsupported predictor mode: %u", predictorMode);
    52
    53    for (uint32 i = 0; i < frame.cps;  i++)
    54      if (frame.compInfo[i].superH != 1 || frame.compInfo[i].superV != 1)
    55        ThrowRDE("Unsupported subsampling");
    56
    57    switch (frame.cps) {
    58    case 2:
    59      decodeN<2>();
    60      break;
    61    case 3:
    62      decodeN<3>();
    63      break;
    64    case 4:
    65      decodeN<4>();
    66      break;
    67    default:
    68      ThrowRDE("Unsupported number of components: %u", frame.cps);
    69    }
    70  }
