    35  void AbstractLJpegDecompressor::decode() {
    36    if (getNextMarker(false) != M_SOI)
    37      ThrowRDE("Image did not start with SOI. Probably not an LJPEG");
    38
    39    JpegMarker m;
    40    do {
    41      m = getNextMarker(true);
    42
    43      switch (m) {
    44      case M_DHT:
    45        parseDHT();
    46        break;
    47      case M_SOF3:
    48        parseSOF(&frame);
    49        break;
    50      case M_SOS:
    51        parseSOS();
    52        break;
    53      case M_DQT:
    54        ThrowRDE("Not a valid RAW file.");
    55        break;
    56      default: // Just let it skip to next marker
    57        break;
    58      }
    59    } while (m != M_EOI);
    60  }
