    62  void AbstractLJpegDecompressor::parseSOF(SOFInfo* sof) {
    63    uint32 headerLength = input.getU16();
    64    sof->prec = input.getByte();
    65    sof->h = input.getU16();
    66    sof->w = input.getU16();
    67    sof->cps = input.getByte();
    68
    69    if (sof->h == 0 || sof->w == 0)
    70      ThrowRDE("Frame width or height set to zero");
    71
    72    if (sof->prec > 16)
    73      ThrowRDE("More than 16 bits per channel is not supported.");
    74
    75    if (sof->cps > 4 || sof->cps < 1)
    76      ThrowRDE("Only from 1 to 4 components are supported.");
    77
    78    if (headerLength != 8 + sof->cps*3)
    79      ThrowRDE("Header size mismatch.");
    80
    81    for (uint32 i = 0; i < sof->cps; i++) {
    82      sof->compInfo[i].componentId = input.getByte();
    83      uint32 subs = input.getByte();
    84      frame.compInfo[i].superV = subs & 0xf;
    85      frame.compInfo[i].superH = subs >> 4;
    86      uint32 Tq = input.getByte();
    87      if (Tq != 0)
    88        ThrowRDE("Quantized components not supported.");
    89    }
    90    sof->initialized = true;
    91
    92    mRaw->metadata.subsampling.x = sof->compInfo[0].superH;
    93    mRaw->metadata.subsampling.y = sof->compInfo[0].superV;
    94  }
